(6642012, 991307, 69446, '<td valign="top">I like the abstractness of your entry, however the "burnt" look of the image (coupled with the high noise) made it a bit harder for me to appreciate the DoF.</td>', 'I like the abstractness of your entry, however the "burnt" look of the image (coupled with the high noise) made it a bit harder for me to appreciate the DoF.', '2012-01-11 11:17:46.000000', NULL, 1),
(6642014, 990858, 69446, '<td valign="top">Interesting image, and addresses the challenge nicely. Well done.</td>', 'Interesting image, and addresses the challenge nicely. Well done.', '2012-01-11 11:18:52.000000', NULL, 1),
(6642017, 991426, 69446, '<td valign="top">Delicious, I love the water dropness. Great sharpness in the focus sections. Well done, this should do very well.</td>', 'Delicious, I love the water dropness. Great sharpness in the focus sections. Well done, this should do very well.', '2012-01-11 11:19:38.000000', NULL, 1),
(6642020, 991414, 69446, '<td valign="top">Nice idea, for me personally a bit less saturation would help. Composition wise, a bit more or less negative space on the right may have helped... it doesn''t quite seem balanced as it stands. Overall, good job.</td>', 'Nice idea, for me personally a bit less saturation would help. Composition wise, a bit more or less negative space on the right may have helped... it doesn''t quite seem balanced as it stands. Overall, good job.', '2012-01-11 11:21:29.000000', NULL, 1),
