(6642024, 991637, 69446, '<td valign="top">Ha, it looks like a character from "angry birds". Nice capture.</td>', 'Ha, it looks like a character from "angry birds". Nice capture.', '2012-01-11 11:24:47.000000', NULL, 1),
(6642025, 991610, 69446, '<td valign="top">Ahh, my favourite fruit! Capture is sharp, the black levels are a bit light for my tastes but overall nice work.</td>', 'Ahh, my favourite fruit! Capture is sharp, the black levels are a bit light for my tastes but overall nice work.', '2012-01-11 11:25:42.000000', NULL, 1),
