(6642030, 991707, 69446, '<td valign="top">I suspect you''ll get punished for minimal red, but I really like it... simple but effective. 8 from me.</td>', 'I suspect you''ll get punished for minimal red, but I really like it... simple but effective. 8 from me.', '2012-01-11 11:28:18.000000', NULL, 1),
(6642031, 991370, 69446, '<td valign="top">The DoF really needs to be shallower... most of the image is in focus. I suspect you need a lens with a wider aperture (or a longer telephoto lens at full zoom).</td>', 'The DoF really needs to be shallower... most of the image is in focus. I suspect you need a lens with a wider aperture (or a longer telephoto lens at full zoom).', '2012-01-11 11:29:23.000000', NULL, 1),
(6642036, 991902, 69446, '<td valign="top">Interesting composition... I found the haloing around the foreground light a bit off-putting but that''s minor. Skin tones are also a bit soft, not sure if that''s your lens or the processing... overall, well done.</td>', 'Interesting composition... I found the haloing around the foreground light a bit off-putting but that''s minor. Skin tones are also a bit soft, not sure if that''s your lens or the processing... overall, well done.', '2012-01-11 11:30:50.000000', NULL, 1),
(6642040, 991692, 69446, '<td valign="top">Nice capture, I''d have liked to see a stronger fall-off in focus... the back of the bird is still reasonably sharp.</td>', 'Nice capture, I''d have liked to see a stronger fall-off in focus... the back of the bird is still reasonably sharp.', '2012-01-11 11:31:55.000000', NULL, 1),
(6642044, 991298, 69446, '<td valign="top">Interesting shot... while I normally appreciate dark &amp; murky photos, I think it works against you in this challenge because it makes the shallow DoF much harder to see. You get points for being different :)</td>', 'Interesting shot... while I normally appreciate dark & murky photos, I think it works against you in this challenge because it makes the shallow DoF much harder to see. You get points for being different :)', '2012-01-11 11:33:05.000000', NULL, 1),
