(6642055, 991848, 69446, '<td valign="top">Nice idea, I think the shot may have worked better if you angled the camera so that her body was fading out of focus. With the current pose, the overwhelming majority of the image is sharp, removing emphasis from the shallow DoF. Kudos for being bold, well done.</td>', 'Nice idea, I think the shot may have worked better if you angled the camera so that her body was fading out of focus. With the current pose, the overwhelming majority of the image is sharp, removing emphasis from the shallow DoF. Kudos for being bold, well done.', '2012-01-11 11:38:01.000000', NULL, 1),
(6642057, 991415, 69446, '<td valign="top">Ha ha, magnificent. You''ll probably get punished, but I appreciate the humour. Well done!</td>', 'Ha ha, magnificent. You''ll probably get punished, but I appreciate the humour. Well done!', '2012-01-11 11:38:59.000000', NULL, 1),
