(6642416, 991846, 35086, '<td valign="top">Lovely image but you''re really winning me over with those strawberries.  XD</td>', 'Lovely image but you''re really winning me over with those strawberries.  XD', '2012-01-11 16:26:09.000000', NULL, 1),
(6642418, 991391, 35086, '<td valign="top">Ah, that''s such a very original idea!</td>', 'Ah, that''s such a very original idea!', '2012-01-11 16:27:53.000000', NULL, 1),
(6642419, 991660, 35086, '<td valign="top">Very sharp and very lovely.</td>', 'Very sharp and very lovely.', '2012-01-11 16:29:27.000000', NULL, 1),
(6642421, 991787, 35086, '<td valign="top">Wow, such a cool idea.  I''m trying to figure out how you set this up... amazing job.</td>', 'Wow, such a cool idea.  I''m trying to figure out how you set this up... amazing job.', '2012-01-11 16:30:17.000000', NULL, 1),
(6642422, 991773, 35086, '<td valign="top">Well set up and love that light.</td>', 'Well set up and love that light.', '2012-01-11 16:31:13.000000', NULL, 1),
(6642424, 991181, 35086, '<td valign="top">Pink isn''t my favorite color but works so well here.  Very nice colors, balance and overall image.</td>', 'Pink isn''t my favorite color but works so well here.  Very nice colors, balance and overall image.', '2012-01-11 16:32:23.000000', NULL, 1),
(6642428, 991725, 35086, '<td valign="top">That snake just makes it that much more powerful.  Good shot.</td>', 'That snake just makes it that much more powerful.  Good shot.', '2012-01-11 16:34:11.000000', NULL, 1),
(6642429, 991839, 35086, '<td valign="top">Cute :)</td>', 'Cute :)', '2012-01-11 16:34:39.000000', NULL, 1),
(6642435, 991474, 35086, '<td valign="top">Love the lighting and the steam, so well capture, I love it.</td>', 'Love the lighting and the steam, so well capture, I love it.', '2012-01-11 16:37:37.000000', NULL, 1),
(6642436, 991894, 35086, '<td valign="top">Perhaps too much red?</td>', 'Perhaps too much red?', '2012-01-11 16:38:06.000000', NULL, 1),
(6642437, 991922, 35086, '<td valign="top">Love the cross pattern created by the candy cane and the background, very good idea!</td>', 'Love the cross pattern created by the candy cane and the background, very good idea!', '2012-01-11 16:38:41.000000', NULL, 1),
(6642441, 991448, 35086, '<td valign="top">Roses have been overdone, I was kind of expecting that but the execution and composition here is great so I won''t hold it against you.</td>', 'Roses have been overdone, I was kind of expecting that but the execution and composition here is great so I won''t hold it against you.', '2012-01-11 16:40:37.000000', NULL, 1),
(6642446, 991272, 35086, '<td valign="top">I like the intensity here, you really went all out for this shot too which is something that''s always worth a lot.  Good dedication and execution.</td>', 'I like the intensity here, you really went all out for this shot too which is something that''s always worth a lot.  Good dedication and execution.', '2012-01-11 16:47:20.000000', NULL, 1),
(6642486, 991470, 12611, '<td valign="top">Nice graphic quality, remindas me a bit of bacon.</td>', 'Nice graphic quality, remindas me a bit of bacon.', '2012-01-11 18:36:47.000000', NULL, 1),
(6642491, 991874, 51747, '<td valign="top">I like the shot and would have scored it higher if the wagon were shown in red.</td>', 'I like the shot and would have scored it higher if the wagon were shown in red.', '2012-01-11 18:39:22.000000', NULL, 1);
