(6645568, 991865, 66384, '<td valign="top">Lovely background, and I like the arc of the leaves, and the punctuation of the berries.</td>', 'Lovely background, and I like the arc of the leaves, and the punctuation of the berries.', '2012-01-15 17:27:21.000000', NULL, 1),
(6645572, 991604, 66384, '<td valign="top">Beautiful lines and movement. I like the design and use of negative space.</td>', 'Beautiful lines and movement. I like the design and use of negative space.', '2012-01-15 17:31:16.000000', NULL, 1),
(6645575, 990858, 66384, '<td valign="top">Love it! The design is excellent, and the hint of a face in the dark is wonderfully intriguing.</td>', 'Love it! The design is excellent, and the hint of a face in the dark is wonderfully intriguing.', '2012-01-15 17:36:12.000000', NULL, 1),
(6645586, 991726, 66384, '<td valign="top">Not much red in this. I would prefer to see both volumes of Gilliver in focus, then there would be some reason for the shallow DOF.</td>', 'Not much red in this. I would prefer to see both volumes of Gilliver in focus, then there would be some reason for the shallow DOF.', '2012-01-15 17:43:10.000000', NULL, 1),
(6645589, 991728, 66384, '<td valign="top">There is a significant amount of noise in this, as if it were taken with a camera that doesn''t handle the low light well, e.g. iPhone. I like the idea and the composition.</td>', 'There is a significant amount of noise in this, as if it were taken with a camera that doesn''t handle the low light well, e.g. iPhone. I like the idea and the composition.', '2012-01-15 17:47:32.000000', NULL, 1),
(6645592, 991415, 66384, '<td valign="top">.</td>', '.', '2012-01-15 17:53:11.000000', NULL, 1),
(6645598, 991599, 66384, '<td valign="top">Seams shallow to me. Meets the challenge, but not very interesting, and the red in the background seems blown out.</td>', 'Seams shallow to me. Meets the challenge, but not very interesting, and the red in the background seems blown out.', '2012-01-15 17:59:17.000000', NULL, 1),
(6645599, 991275, 66384, '<td valign="top">Very nice design, and one of the few which really meet the challenge.</td>', 'Very nice design, and one of the few which really meet the challenge.', '2012-01-15 18:01:47.000000', NULL, 1),
(6645601, 991705, 66384, '<td valign="top">Nice image. I like the subject, color, and composition, but I am not seeing the shallow DOF.</td>', 'Nice image. I like the subject, color, and composition, but I am not seeing the shallow DOF.', '2012-01-15 18:06:01.000000', NULL, 1),
(6645604, 991874, 66384, '<td valign="top">You are really asking for the DNMC votes. Nice image and shallow DOF, though.</td>', 'You are really asking for the DNMC votes. Nice image and shallow DOF, though.', '2012-01-15 18:10:46.000000', NULL, 1),
(6645610, 991748, 66384, '<td valign="top">I would say blue was the primary color of this image -- two people wearing blue against a blue sea and blue sky.</td>', 'I would say blue was the primary color of this image -- two people wearing blue against a blue sea and blue sky.', '2012-01-15 18:14:24.000000', NULL, 1),
(6645614, 990941, 66384, '<td valign="top">Beautiful DOF and design, and definitely red. Well done.</td>', 'Beautiful DOF and design, and definitely red. Well done.', '2012-01-15 18:18:11.000000', NULL, 1),
(6645618, 991869, 66384, '<td valign="top">Nice, clean, and simple.</td>', 'Nice, clean, and simple.', '2012-01-15 18:22:06.000000', NULL, 1),
(6645625, 991600, 66384, '<td valign="top">Gorgeous DOF and color. I love the creamy softness.</td>', 'Gorgeous DOF and color. I love the creamy softness.', '2012-01-15 18:34:23.000000', NULL, 1),
(6645632, 991466, 66384, '<td valign="top">Lovely DOF, and focus on your subject. The tones are beautiful.</td>', 'Lovely DOF, and focus on your subject. The tones are beautiful.', '2012-01-15 18:37:44.000000', NULL, 1),
(6645636, 991134, 120171, '<td valign="top">The title certainly reflects the image, the type of image you see blown up on canvas. 10.</td>', 'The title certainly reflects the image, the type of image you see blown up on canvas. 10.', '2012-01-15 18:43:53.000000', NULL, 1),
(6645637, 991859, 120171, '<td valign="top">I love the simplicity of this shot, nothing elaborate just good light and composition.</td>', 'I love the simplicity of this shot, nothing elaborate just good light and composition.', '2012-01-15 18:45:05.000000', NULL, 1),
(6645638, 991018, 120171, '<td valign="top">This image caught my eye immediately, i just wish it was little brighter. Hope this one does well.</td>', 'This image caught my eye immediately, i just wish it was little brighter. Hope this one does well.', '2012-01-15 18:46:34.000000', NULL, 1),
(6645660, 991874, 97225, '<td valign="top">You have the shallow dof, but I needed to see red. (I realize that the subject may well be red, I just needed to see it.)</td>', 'You have the shallow dof, but I needed to see red. (I realize that the subject may well be red, I just needed to see it.)', '2012-01-15 19:06:25.000000', NULL, 1),
(6645661, 991474, 97225, '<td valign="top">Beautifully done. One of my top picks.</td>', 'Beautifully done. One of my top picks.', '2012-01-15 19:07:36.000000', NULL, 1),
(6645662, 991426, 97225, '<td valign="top">Beautiful image, great handling of the red and shallow dof. One of my top few.</td>', 'Beautiful image, great handling of the red and shallow dof. One of my top few.', '2012-01-15 19:09:44.000000', NULL, 1),
