(6647339, 991768, 63812, '<td valign="top">underrated image. I voted 10 and really like it. Nice job</td>', 'underrated image. I voted 10 and really like it. Nice job', '2012-01-17 01:01:52.000000', NULL, 0),
(6647352, 991474, 108580, '<td valign="top">It''s refreshing to see that good photography is still rewarded. That shallow DOF is sublime. Well done on the teamwork. One thing though, did you seriously need to deNoise a shot from the legendary noiseless D3? hehe.</td>', 'It''s refreshing to see that good photography is still rewarded. That shallow DOF is sublime. Well done on the teamwork. One thing though, did you seriously need to deNoise a shot from the legendary noiseless D3? hehe.', '2012-01-17 02:04:45.000000', NULL, 0),
