(6648530, 991678, 136013, '<td valign="top">Thanks for all the great comments everyone.. Guess this was a nice first picture to put on DPChallenge.</td>', 'Thanks for all the great comments everyone.. Guess this was a nice first picture to put on DPChallenge.', '2012-01-18 10:34:23.000000', NULL, 0),
